WITH base AS (SELECT * FROM departments WHERE location = 'London'), Summary AS (SELECT CASE WHEN budget >= 3330000 THEN 'high' WHEN budget >= 1690000 THEN 'mid' ELSE 'low' END AS budget_bucket, dept_name, SORT_ARRAY(COLLECT_SET(location)) AS location_list, ROUND(AVG(budget), 2) AS avg_budget FROM base GROUP BY CASE WHEN budget >= 3330000 THEN 'high' WHEN budget >= 1690000 THEN 'mid' ELSE 'low' END, dept_name) SELECT * FROM Summary ORDER BY dept_name, budget_bucket
